# Use Actions

Use actions are the rules-layer contract for item-driven actions that need more
than a one-shot `onUse` hook.

Items keep their authored identity and UI affordances in `src/content/items/*`.
The matching rules behavior is registered once with `defineUseAction(identity,
def)`. Systems and app wiring look up the action by item identity instead of
branching on specific ids.

```js
defineUseAction("fishing_rod", {
  channelTurns: 12,
  targeting: {
    name: "Fishing",
    fallbackRange: 6,
    validateTarget(x, y) {
      return isFishableTile(getTile(x, y)) ? null : "Fishing must target water.";
    },
    onConfirm(world, actorId, itemId, x, y) {
      world.emit("fishing:cast:request", { actor: actorId, itemId, x, y });
    },
  },
  onComplete(world, actorId, channel) {
    // Resolve the completed item channel.
  },
});
```

Rules:

- Register from an install function called once per world with a domain-specific
  `Symbol.for("jshack:<domain>:<what>:installed")` guard when listeners are
  involved.
- Store active channel state on `Channeling.itemActionId`; `channelingSystem`
  dispatches completion through `getUseAction()`.
- Keep targeting metadata presentation-neutral. App/display code may use it to
  open a targeter, but rules validation and completion stay in rules/content.
- New tools should add a declaration here rather than editing
  `castSpellSystem`, `channelingSystem`, or `main.js` for identity-specific
  branches.
import { ItemAbilityActivated } from "../../../events/ItemAbilityActivated.js";
import { Charges } from "../../components/Charges.js";
import { Faction } from "../../components/Faction.js";
import { Position } from "../../components/Position.js";
import { Vitality } from "../../components/Vitality.js";
import { getItemCooldownRemaining } from "../../utils/itemCooldowns.js";
import { areFactionsHostile, areFactionsAllied } from "../../utils/factionHostility.js";
import { hasSpellLineOfSight } from "../../utils/spellTargeting.js";
import { buildBlocksVisionMap, blockedCallback } from "../../utils/vision.js";

// Ownership is checked by usePipeline before reaching this named activation.
export function itemAbilityPipeline(ctx, spec, state, equippedSlot) {
  const { actor, itemId, identity } = state;
  const fail = (code, message) => ctx.cancel({ code: `ABILITY_${code}`, message, consumesTurn: false });
  if (ctx.query.get(actor, Vitality)?.hp <= 0) return fail("DEAD_ACTOR", "You cannot act.");
  if (spec.requiresEquipped && !equippedSlot) return fail("NOT_EQUIPPED", "Equip this item first.");
  if (getItemCooldownRemaining(ctx.world, itemId) > 0) return fail("COOLDOWN", "This item is cooling down.");
  const charges = ctx.query.get(itemId, Charges);
  if (spec.chargeCost > 0 && (!charges || charges.current < spec.chargeCost)) return fail("CHARGES", "This item has insufficient charges.");
  const targetId = spec.targeting === "none" ? actor : ctx.target;
  if (spec.targeting !== "none") {
    const vital = ctx.query.get(targetId, Vitality);
    if (!ctx.query.alive(targetId) || !vital || vital.hp <= 0) return fail("TARGET", "Choose a living target.");
    const actorFaction = ctx.query.get(actor, Faction)?.key;
    const targetFaction = ctx.query.get(targetId, Faction)?.key;
    if (spec.targeting === "enemy" && (targetId === actor || !areFactionsHostile(actorFaction, targetFaction))) return fail("TARGET", "Choose an enemy.");
    if (spec.targeting === "ally" && targetId !== actor && !areFactionsAllied(actorFaction, targetFaction)) return fail("TARGET", "Choose an ally.");
    const from = ctx.query.get(actor, Position);
    const to = ctx.query.get(targetId, Position);
    if (!from || !to || Math.max(Math.abs(from.x - to.x), Math.abs(from.y - to.y)) > spec.range) return fail("RANGE", "Target is out of range.");
    const isBlocked = blockedCallback(buildBlocksVisionMap(ctx.world, { x0: from.x - spec.range, y0: from.y - spec.range, x1: from.x + spec.range, y1: from.y + spec.range }));
    if (!hasSpellLineOfSight(ctx.world, { sourceId: actor, targetId, sourcePos: from, targetPos: to, range: spec.range, isBlocked })) return fail("LOS", "Target is out of sight.");
  }
  for (const effect of spec.effects || []) {
    ctx.mutate.pushEffect(effect.target === "self" ? actor : targetId, { ...effect, sourceId: itemId, sourceActorId: actor, sourceKind: "item", sourceKey: identity });
  }
  const result = spec.activate ? spec.activate(ctx, { ...state, target: targetId }) : {};
  if (ctx.cancelled) return;
  if (charges && spec.chargeCost > 0) ctx.mutate.patchComponent(itemId, Charges, { current: charges.current - spec.chargeCost });
  if (spec.cooldown > 0) ctx.mutate.queue({ type: "setItemCooldown", entityId: itemId, turns: spec.cooldown });
  if (result?.consumed) {
    ctx.mutate.consume(itemId, actor);
    ctx.io.emit("item:used", { actor, itemId });
  }
  ctx.io.emit(new ItemAbilityActivated({ actor, itemId, targetId, abilityId: spec.id }));
  return { metrics: { path: "ability", consumed: result?.consumed === true }, payload: { abilityId: spec.id } };
}
}

function requestFishingCast(world, actor, itemId, opts = {}) {
  const turns = Math.max(1, Number(opts?.turns || 12) | 0);
  const eq = world.get(actor, Equipment);
  if (!getEquippedSlot(eq, itemId)) {
    world.emit("item:use-cancelled", {
      actor,
      itemId,
      code: "FISHING_ROD_NOT_EQUIPPED",
      message: "Equip the fishing rod before casting.",
      consumesTurn: false,
    });
    return false;
  }
  if (world.has(actor, Channeling)) {
    world.emit("item:use-cancelled", {
      actor,
      itemId,
      code: "FISHING_ALREADY_CHANNELING",
      message: "You are already channeling.",
      consumesTurn: false,
    });
    return false;
  }

  const water = findFishingWater(world, actor, opts?.intent || opts);
  if (!water) {
    world.emit("item:use-cancelled", {
      actor,
      itemId,
      code: "FISHING_NO_WATER",
      message: "There is no fishable water in casting range.",
      consumesTurn: false,
    });
    return false;
  }

  const pos = world.get(actor, Position);
  const spotId = findReadyFishingSpotAt(world, water.x, water.y);
  try {
    world.add(actor, Channeling, {
      mode: "cast",
      turnsRemaining: turns,
      turnsTotal: turns,
      spellId: "fishing",
      itemActionId: "fishing_rod",
      targetId: spotId || itemId,
      x: water.x,
      y: water.y,
      breakOnMove: true,
      anchorX: pos ? (pos.x | 0) : null,
      anchorY: pos ? (pos.y | 0) : null,
    });
  } catch {}
  world.emit("channeling:start", { actor, spellId: "fishing", castTime: turns, mode: "fish", itemId, x: water.x, y: water.y });
  world.emit("fishing:cast", { actor, itemId, x: water.x, y: water.y, turns, spotId });
  return true;
}

function resolveFishingChannel(world, actor, ch) {
  const pos = world.get(actor, Position);
  const targetId = Number(ch?.targetId || 0) | 0;
  const node = targetId > 0 ? world.get(targetId, HarvestNode) : null;
  const useSpot = !!node && String(node.kind || "") === "fishing_spot" && node.ready === true;
  const tableId = useSpot ? "fishing:spot" : "fishing:normal_water";
  const tile = getTile(Number(ch.x || 0) | 0, Number(ch.y || 0) | 0);
  const tileProfile = fishingTileProfile(tile);
  const raining = isFishingRain(world);
  const pressureBefore = Math.max(
    readFishingPressure(world, ch.x, ch.y),
    useSpot ? (Number(node.fishingPressure || 0) | 0) : 0,
  );
  const seed = ((Number(world.seed || 0) >>> 0) ^ Math.imul(Number(world.step || 0) | 0, 0x9e3779b1) ^ Math.imul(actor | 0, 0x85ebca6b)) >>> 0;
  const rng = createRng(seed);
  const drops = resolveFishingDrops(tableId, rng, { tileProfile, raining, pressure: pressureBefore });
    raining,
    pressureBefore,
    pressureAfter,
  });
}

