      ex: pos.x + 0.5, ey: pos.y + 0.5,
      charge: chargeCount,
      total: total || 8,
      turn: Number.isFinite(turn) ? (turn | 0) : -1,
    });
  });

  // Gaze stun fires — bright flash then clear the beam
  world.on('proc:gaze:stun', ({ actor }) => {
